Actionscript.script:
声音 = "";
霰弹值 = 1;
子弹散射度 = 0;
发射效果 = "";
子弹种类 = "g1炮弹击中";
if(!子弹威力)
{
   子弹威力 = 300;
}
else
{
   子弹威力 *= 0.7;
}
子弹速度 = 0;
击中地图效果 = "";
击退初速度 = 5
Z轴攻击范围 = 80;
 击倒率 = 1;
 击中后子弹的效果 = "";
 shootX = this._x;
 shootY = this._y;

 var 子弹属性 = _root.子弹属性初始化(this,子弹种类,发射者名);
 子弹属性.声音 = 声音;
 子弹属性.霰弹值 = 霰弹值;
 子弹属性.子弹散射度 = 子弹散射度;
 子弹属性.发射效果 = 发射效果;
 子弹属性.子弹种类 = 子弹种类;
 子弹属性.子弹威力 = 子弹威力;
 子弹属性.子弹速度 = 子弹速度;
 子弹属性.Z轴攻击范围 = Z轴攻击范围;
 子弹属性.击中地图效果 = 击中地图效果;
 子弹属性.击倒率 = 击倒率;
 子弹属性.击中后子弹的效果 = 击中后子弹的效果;
 子弹属性.shootX = shootX;
 子弹属性.shootY = shootY;
 子弹属性.shootZ = Z轴坐标;
 子弹属性.发射者 = 发射者名;

 // 锁定发射瞬间的属性，避免切换武器/模组后爆炸继承到当前主角属性
 子弹属性.伤害类型 = (this.伤害类型 != undefined) ? this.伤害类型 : "物理";
 子弹属性.魔法伤害属性 = this.魔法伤害属性;
 子弹属性.毒 = this.毒;
 子弹属性.nanoToxic = this.nanoToxic;
 子弹属性.nanoToxicDecay = this.nanoToxicDecay;
 子弹属性.吸血 = this.吸血;
 子弹属性.击溃 = this.击溃;
 子弹属性.斩杀 = this.斩杀;
 子弹属性.暴击 = this.暴击;
 子弹属性.命中率 = this.命中率;
 子弹属性.固伤 = this.固伤;
 子弹属性.百分比伤害 = this.百分比伤害;
 子弹属性.血量上限击溃 = this.血量上限击溃;
 子弹属性.防御粉碎 = this.防御粉碎;
 子弹属性.lockShooterAttributes = true;

 _root.子弹区域shoot传递(子弹属性);
 stop();
 this.removeMovieClip();

onClipEvent(load){
   垂直速度 = -5;
   起始Y = _parent.Z轴坐标;
   this.onEnterFrame = function()
   {
      _parent._y += 垂直速度;
      垂直速度 += _root.重力加速度;
      if(_parent._y >= 起始Y)
      {
         _parent._y = 起始Y;
         delete this.onEnterFrame;
         _parent.gotoAndPlay("消失");
      }
   };
}
